mermaid:
flowchart TD
    START_NODE["Sensor Telemetry Ingestion [x(k)]<br/><small><i>x(k) = C*x_hat + e</i></small>"]
    HORIZON_PRED["State Trajectory Prediction [N_p]<br/><small><i>y_pred = A^i * x(k)</i></small>"]
    QP_OPTIMIZER["Constrained QP Solver [min J]<br/><small><i>min sum(e^T Q e + Delta u^T R Delta u)</i></small>"]
    FEASIBILITY_CHECK{"Feasibility & Invariant Check<br/><small><i>u_min <= u <= u_max & |Delta u| <= Delta u_max</i></small>"}
    TRIPWIRE_FALLBACK["🛑 TRIPWIRE: Safe Hold / Infeasible Abort<br/><small><i>u(k) = u_safe, Alert SIRT</i></small>"]
    ACTUATOR_DISPATCH["Receding Horizon Dispatch [u*(k)]<br/><small><i>Apply u*(k), Shift k -> k+1</i></small>"]
    START_NODE --> HORIZON_PRED
    HORIZON_PRED --> QP_OPTIMIZER
    QP_OPTIMIZER --> FEASIBILITY_CHECK
    FEASIBILITY_CHECK -- "Constraint Violated OR Infeasible" --> TRIPWIRE_FALLBACK
    FEASIBILITY_CHECK -- "All Invariants Satisfied" --> ACTUATOR_DISPATCH

    classDef intake fill:#e0f2fe,stroke:#0284c7,stroke-width:2px,color:#0369a1;
    classDef optimizer fill:#f0fdf4,stroke:#16a34a,stroke-width:2px,color:#15803d;
    classDef decision fill:#fffbeb,stroke:#d97706,stroke-width:2px,color:#b45309;
    classDef tripwire fill:#fef2f2,stroke:#dc2626,stroke-width:2px,color:#991b1b;
    classDef terminal fill:#f8fafc,stroke:#475569,stroke-width:2px,color:#1e293b;
    class START_NODE intake;
    class HORIZON_PRED optimizer;
    class QP_OPTIMIZER optimizer;
    class FEASIBILITY_CHECK decision;
    class TRIPWIRE_FALLBACK tripwire;
    class ACTUATOR_DISPATCH terminal;
